class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        stack = 0
        result = []
        for char in s:
            if char == '(':
                stack += 1
            else:
                stack -= 1
                if stack == 0:
                    result.append(char * 2)
        return ''.join(result)
